catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading) return;

    g_form.hideFieldMsg('amount', true);

    if (!newValue) return;

    var rewardTypeSysId = g_form.getValue('reward_type');
    if (!rewardTypeSysId) {
        g_form.showFieldMsg('amount', 'Please select a reward type first.', 'info', true);
        return;
    }

    // Look up min_value and max_value from the selected reward catalog entry
    g_form.getReference('reward_type', function (ref) {
        if (!ref) return;

        var minValue = parseFloat(ref.min_value);
        var maxValue = parseFloat(ref.max_value);
        var enteredAmount = parseFloat(newValue);

        if (isNaN(enteredAmount)) {
            g_form.showFieldMsg('amount', 'Please enter a valid number.', 'error', true);
            g_form.clearValue('amount');
            return;
        }

        if (!isNaN(minValue) && enteredAmount < minValue) {
            g_form.showFieldMsg('amount', 'Amount must be at least ' + minValue + '.', 'error', true);
            g_form.clearValue('amount');
            return;
        }

        if (!isNaN(maxValue) && enteredAmount > maxValue) {
            g_form.showFieldMsg('amount', 'Amount cannot exceed ' + maxValue + '.', 'error', true);
            g_form.clearValue('amount');
            return;
        }
    });
}
